from pathlib import Path
import json,re,hashlib
from datetime import datetime,timezone
root=Path(__file__).resolve().parents[4];out=Path(__file__).parent
read=lambda p:p.read_text(encoding='utf-8-sig')
save=lambda p,d:p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
gp=out/'f03-owner-gate-2026-10-09.json';g=json.loads(read(gp));assert g['status']=='PENDING_OWNER_APPROVAL'
peak=root/g['candidate'];assert hashlib.sha256(peak.read_bytes()).hexdigest()==g['sha256']
receipt=out/'f03-owner-approval-2026-10-09.json';assert not receipt.exists()
save(receipt,dict(timestamp=datetime.now(timezone.utc).isoformat(),plan='PLAN-053',spec='SPEC-121',classification='IN_PLAN',status='APPROVED',owner_reply='atena, aprovado, continue',context='Reply to F03 approval question for generation of five remaining fire arc frames',gate_id=g['id'],frame='F03',version='v01',sha256=g['sha256'],scope='Visual F03 peak approval; five other F frames, then next existing FILA022 P01 gate; future unseen frames not approved',runtime_admission=False))
g.update(status='APPROVED',owner_reply='atena, aprovado, continue',approval_receipt=receipt.relative_to(root).as_posix());save(gp,g)
canon=root/'.atena/vault/canon/ASSET-APPROVAL-REGISTER-026-vfx-arco-fogo-2026-10-09.md';assert not canon.exists()
canon.write_text('# ASSET-APPROVAL-REGISTER-026 — Pico do arco de fogo\n\nApós a pergunta “Aprova F03 para gerar os cinco quadros restantes?”, o dono respondeu “atena, aprovado, continue”. F03 peak v01 aprovada visualmente, SHA256 '+g['sha256']+'. [Aprovação](../../generated/s007-reconciliation/v01/f03-owner-approval-2026-10-09.json), [fonte aprovada](../../generated/art-candidates/vfx/arco_largo_fogo/arco_largo_fogo_peak_v01.png).\n\nPLAN-053/SPEC-121, IN_PLAN, per-plan preservado. Gerar os cinco demais quadros F usando o pico aprovado, depois seguir até o gate P01 da FILA022. Esse próximo gate permanece obrigatório; nenhuma aprovação individual fictícia de quadros futuros. Fontes nativas preservadas e normalização técnica futura registrada; nenhuma admissão runtime nesta fila, sem autorização Git/publicação.\n',encoding='utf-8')
q21=root/'.atena/generated/CHATGPT-FILA-021-vfx-corpo-a-corpo-excecoes.md';t=read(q21);old='- [x] gerada · [ ] aprovada · candidata: `'+g['candidate']+'` — F03 v01: gate humano pendente; fonte nativa preservada.';assert old in t
t=t.replace(old,old.replace('[ ] aprovada','[a] aprovada').replace('gate humano pendente','aprovada pelo dono em 2026-10-09')).replace('F03 v01 com gate pendente','F03 v01 aprovada; cinco demais F em geração');q21.write_text(t,encoding='utf-8')
q22=root/'.atena/generated/CHATGPT-FILA-022-vfx-projeteis-e-explosoes.md';p22=read(q22);pilot=out/'approved-pilot-A03-v02-reference.png';jobs=[]
phase_notes={'F01':'START geometry: ONE thin simple C-shaped early arc opening LEFT and bulging RIGHT, about one quarter of the approved peak reach. A tiny weak sliver near the canvas-center pivot, only a few tiny embers. No mirrored pair of lobes, hourglass, inward pinch, or full-size bright peak.','F02':'SWEEP phase: one C-shaped arc opening LEFT and bulging RIGHT, clearly smaller and thinner than F03, about60% of its reach. Bright narrow leading edge, thin faint trailing band, fewer and shorter flame tongues. Do not duplicate the full-size peak.','F04':'HOLD phase after the peak: same full-radius single C-shaped fire arc as F03, opening LEFT, bulging RIGHT; white core clearly narrower and weaker, outer flames ragged and starting to die, substantially fewer embers. Do not duplicate the thick brilliant peak.','F05':'FADE phase: only disconnected broken fragments of the same fire arc remain at the original full-radius positions. Mostly dim GRAY, no continuous bright white band or intact bright crescent. Small fading flame remnants and few dim tiny embers. Much weaker than hold.','F06':'DISSIPATE phase: almost entirely pure BLACK; only a few very faint DARK GRAY wisps and tiny ember specks remain where the right-facing arc was. Nothing bright, no white core, no intact crescent. Preserve the same pivot and spatial layout.'}
for code in ['F01','F02','F04','F05','F06','P01']:
 txt=t if code.startswith('F') else p22
 m=re.search(r'#### '+code+r' - `([^`]+)`.*?```text\s*(.*?)\s*```',txt,re.S);name,prompt=m.groups();effect='arco_largo_fogo' if code.startswith('F') else 'orbe_radiante'
 assert re.search(r'Subject: (.*?) Frame ',prompt).group(1) in read(root/('.atena/generated/ART-PROMPTS-052-vfx-corpo-a-corpo-excecoes.md' if code.startswith('F') else '.atena/generated/ART-PROMPTS-053-vfx-projeteis-e-explosoes.md'))
 dest=root/f'.atena/generated/art-candidates/vfx/{effect}/{name}_v01.png';assert not dest.exists();dest.parent.mkdir(parents=True,exist_ok=True)
 if code.startswith('F'):
  refs=[str(peak),str(pilot)];prompt+='\n\nReference1 is the APPROVED F03 peak for this exact fire arc. Reference2 is the APPROVED physical pilot for painted white-core/gray-glow STYLE ONLY. Generate ONLY '+code+' phase specified above. Keep the same ground-flat orientation, exact canvas-center pivot and RIGHT-facing direction. Preserve painted flame texture but strictly neutral white/gray, no orange or red. All glow, flame tips and embers must fit inside black margins.\n'+phase_notes[code]
 else:
  refs=[str(pilot)];prompt+='\n\nThe attached approved physical pilot is a STYLE REFERENCE ONLY for painted light texture, white core and gray soft falloff. Generate a NEW round radiant projectile, not an arc. The round orb core must be centered at the exact canvas center, with a SHORT pointed tail streaming directly LEFT because it travels RIGHT. No 3D sphere shading, no perspective, no crescent blade, no color. Only this one first flight frame, with orb, halo, tail and few tiny star sparks comfortably inside pure-black margins.'
 jobs.append(dict(code=code,effect=effect,name=name,version='v01',prompt=prompt,referenced_image_paths=refs,destination=dest.relative_to(root).as_posix(),status='PENDING',transparent_background=False,source_queue=q21.relative_to(root).as_posix() if code.startswith('F') else q22.relative_to(root).as_posix()))
save(out/'fp-generation-jobs-2026-10-09.json',dict(plan='PLAN-053',spec='SPEC-121',generator='built-in imagegen',remaining_at_start=101,counter_field='native_generated_since_F03',approval_receipt=receipt.relative_to(root).as_posix(),native_originals_preserved=True,jobs=jobs))
for rel in ['.atena/state/plan.yaml','.atena/state/plan-053-imagens.yaml']:
 p=root/rel;s=read(p).replace('AWAITING_OWNER_APPROVAL','EXECUTING_F_REMAINING').replace('S-007/VFX/FILA-021/F03-APPROVAL','S-007/VFX/FILA-021/F-REMAINING')
 s=s.replace('S-007 arco radiante seis fontes revisadas; F03 v01 gerada, gate humano pendente. Manifesto202 preservado.','S-007 F03 aprovada pelo dono; gerando cinco F, depois somente gate P01 FILA022. Manifesto202 preservado.')
 s=s.replace('Aguardar aprovacao F03 antes dos cinco demais F; 101 fontes VFX restantes. Retorno PLAN-071 preservado.','Revisar sequencia F completa; gerar P01 para proximo gate humano. Retorno PLAN-071 preservado.')
 s=s.replace('S-007 arco radiante completo como candidata; aguardando gate humano F03.','S-007 E completo como candidata; F em geracao apos aceite; proximo gate P01.')
 if rel.endswith('plan-053-imagens.yaml'):
  s=s.replace('  id: GATE-FILA-021-F03-2026-10-09\n  status: PENDING_OWNER_APPROVAL','  id: GATE-FILA-021-F03-2026-10-09\n  status: APPROVED')
  s=s.replace('  receipt: .atena/generated/s007-reconciliation/v01/f03-owner-gate-2026-10-09.json\n','  receipt: .atena/generated/s007-reconciliation/v01/f03-owner-gate-2026-10-09.json\n  owner_reply: "atena, aprovado, continue"\n  approval_receipt: .atena/generated/s007-reconciliation/v01/f03-owner-approval-2026-10-09.json\n')
  block=re.search(r'\nvfx_generation_progress:\n(.*?)(?=\n\S|\Z)',s,re.S);assert block
  s=s[:block.start(1)]+'  jobs: .atena/generated/s007-reconciliation/v01/fp-generation-jobs-2026-10-09.json\n  native_generated_since_F03: 0\n  last_frame: none\n'+s[block.end(1):]
 p.write_text(s,encoding='utf-8')
print(json.dumps(dict(status='F03_APPROVED_F_REMAINING_READY',jobs=len(jobs),next_gate='FILA022/P01')))
